T = {
"gs51": ("حافة البلكونة الشمالية الغربية", "لما يصير معك القوس، ارجع للدور الثالث واضرب العين اللي فوق الباب عشان الممر الأحمر يرجع مستقيم. بعد ما تاخذ الـ Boss Key، انزل للدور الأول واطلع على البلكونة اللي فوق الساحة الشمالية الغربية. امشِ جنوب على الحافة بعد الباب ولف مع الزاوية."),
"gs52": ("الحافة العالية فوق الساحة الشمالية الشرقية", "إذا معك مفاتيح كفاية، انزل الممر الأحمر ومر بغرف الـ Poe لين الممر الأزرق، واضرب العين عشان يلتف. انزل للحافة اللي فوق الساحة الشمالية الشرقية، شغّل Scarecrow's Song جنب الريح، وسوّ Hookshot على Pierre عشان توصل العنكبوت."),
"gs53": ("زاوية القبو الجنوبية", "بعد ما تهزم الأربع Poe Sisters وتفتح مصعد القبو، لف في B1 للغرفة الصغيرة اللي جنوب. اقتل الـ Skulltula وشوف يمين. إذا الطريق مسدود، حرّك المماسك."),
"gs54": ("مغارة Song of Storms", "بعد معبد الغابة، وأنت صغير تسلل من الحراس لين المكان اللي كانت تنام فيه Malon. في الزاوية الجنوبية الشرقية جنب الشجرة، شغّل Song of Storms على النبتة اللي شكلها مروحة عشان تنفتح مغارة، وفجّر الجدران المتشققة داخلها."),
"gs55": ("صندوق مغارة السفر بالزمن", "وأنت صغير روح للمستنقع الجنوبي الشرقي جنب الـ Peahats وفجّر الحجر المتشقق عشان تنفتح مغارة. اقتل الـ Skullwalltula العادي مثل ما تقول كتابة الجنية. ارجع وأنت كبير وسوّ Roll في الصندوق اللي يهتز، العنكبوت صار فيه."),
"gs56": ("حافة الريح (كبير)", "وأنت كبير روح لأول ممر شرقي اللي فيه Baby Dodongos. شغّل Scarecrow's Song جنب الحافة العالية اللي فيها ريح، وسوّ Hookshot على Pierre."),
"gs57": ("تحت المنصة اللي بالنص", "بالليل انزل من الحلقة العلوية للدور اللي تحتها وروح ورا المنصة اللي بالنص اللي كان عليها حجر النار. العنكبوت على الصخرة اللي ورا."),
"gs58": ("التربة اللينة برا معبد النار", "بعد ما توصل معبد النار وأنت كبير، ارجع وأنت صغير ومعك حشرة في قنينة وانتقل بـ Bolero of Fire. طلّع الحشرة بسرعة على التربة اللينة اللي قريبة."),
"gs59": ("غرفة البلوك الشمالية الشرقية", "من صالة المدخل، خذ غرفة الحمم الشرقية اللي فيها منصات تتحرك لين الحافة العلوية الشمالية الشرقية. استخدم Song of Time عشان تحرك البلوك الأزرق، ادخل الباب، اهزم الـ Flying Tiles والـ Like Like، وتلقى العنكبوت ورا."),
"gs60": ("الجدار المتشقق في غرفة الصخور", "بعد ما تبني المصعد للدور الثالث، ادخل الغرفة الشرقية اللي فيها صخور تتدحرج. انزل وامشِ شمال مع الجدران لين جدار متشقق؛ فجّره."),
"gs61": ("غرفة الصخور، الجدار الشبكي بالدور الرابع", "بعد ما تستكشف جهتين غرفة الدور الثالث الشرقية وتسابق جدار النار للحافة العالية، اقفز لأول منصة وشغّل Scarecrow's Song عند الريح. سوّ Hookshot على Pierre، بعدين على منصة للدور الرابع. العنكبوت على الجدار الشبكي جنب باب الدور الخامس."),
"gs62": ("حفرة الحمم في الغرفة الدائرية", "خذ نفس طريق الـ Scarecrow والـ Hookshot من غرفة الصخور، بس اطلع للدور الخامس. في الغرفة الدائرية الكبيرة، شوف مع الجدار الداخلي فوق حفرة الحمم."),
"gs63": ("صخرة غرفة المطرقة", "بالـ Megaton Hammer، ارجع لصالة المدخل وطيّح التمثال اللي عند الباب اليمين تحت. في الغرفة اللي فيها Flying Tiles و Like Like، كسّر الصخرة الكبيرة اللي ورا."),
"gs64": ("صخرة رمادية قرب القمة", "بالليل انزل مع الطريق من نافورة الجنية العظيمة باتجاه مدينة الغورون وكسّر الصخرة الرمادية الكبيرة بالمطرقة."),
"gs65": ("صخرة رمادية مكان الـ Bomb Flower القديمة", "وأنت طالع من مدينة الغورون، كسّر الصخرة الرمادية الكبيرة اللي في مكان الـ Bomb Flower اللي كانت لحالها. العنكبوت يطلع بالليل."),
"gs66": ("الجهة الجنوبية من الجزيرة", "وصّل للجزيرة الكبيرة اللي بالنهر بنبتة الفاصوليا أو بدجاجة. روح للحافة العالية في جنوبها وسوّ Hookshot على العنكبوت اللي يطلع بالليل."),
"gs67": ("الجدار الغربي جنب الشلال", "في أعلى النهر جنب الشلال، شوف غرب بالليل. العنكبوت معلّق على الجدار العالي في مدى الـ Hookshot."),
"gs68": ("جنب الشلال المتجمد", "اطلع لأعلى الشلال المتجمد ووجّه يسار من الحافة، على العنكبوت اللي يسار درج غرفة العرش."),
"gs69": ("الجدار الجنوبي في غرفة المناجل", "في أول غرفة كبيرة فيها مناجل تدور و Rupees فضية، تفادى الشفرات وشوف فوق على الجدار الجنوبي."),
"gs70": ("ورا عمود صندوق البوصلة", "بعد أول Blue Fire، ذوّب الثلج الأحمر اللي فوق غرفة المناجل بالقنينة. روح شرق لآخر الممر وشوف ورا العمود الثلجي جنب صندوق الـ Compass."),
"gs71": ("الجدار الواطي في لغز البلوك", "ذوّب الثلج الأحمر اللي سادد الطريق الغربي في غرفة المناجل. بعد منطقة البلوك اللي يتزحلق، اعبر للأرض الثلجية ولف وراك تلقى العنكبوت على جدار واطي."),
"gs72": ("صندوق في بركة المختبر", "البس الـ Iron Boots وانزل لقاع بركة المختبر. سوّ Roll في الصندوق اللي تحت وسوّ Hookshot على العنكبوت اللي يطلع."),
"gs73": ("فتحة B1 فوق غرفة العمود", "والماي مرفوع للدور الثاني، روح لأسفل غرفة العمود وادخل B1. اضرب الزر الأخضر بالـ Hookshot عشان تنفتح فتحة واطلع للعنكبوت."),
"gs74": ("الجدار المتشقق في الغرفة الشرقية", "والماي على الدور الثاني، ارجع للغرفة الشرقية في الدور الأول اللي قابلت فيها روتو واطفُ لين الحافة اللي فيها جدار متشقق. فجّره وتلقى العنكبوت في زاوية الغرفة."),
"gs75": ("صخرة بارزة في مغارة النهر", "بالـ Longshot، انزل لمغارة النهر الطويلة في الدور الثاني. لما يلف الطريق جنوب، لف وراك وسوّ Longshot للصخرة البارزة وأنت تحت الماي."),
"gs76": ("سقف غرفة العمود", "والماي على أول مستوى، ارفعه دور واحد من قاعدة غرفة العمود. استخدم أهداف الـ Hookshot لين أعلى الغرفة وسوّ Longshot على العنكبوت اللي في السقف."),
"gs77": ("ممر الصخور قبل الـ Boss Key", "في الدور الأول، خذ الغرف اللي شمال الغرفة الوسطى لين الممرات الغارقة اللي تتدحرج فيها الصخور. شوف فوق على الحفرة اللي بالنص مقابل الشلال."),
"gs78": ("أعلى الشجرة الكبيرة", "على جزيرة الشجرة الكبيرة، شغّل Sun's Song. سوّ Longshot على النباتات اللي قرب أعلى الشجرة واطلع للعنكبوت."),
"gs79": ("غرفة الـ Like Like، الشمال الشرقي", "في منطقة الممشى المربع الرئيسي، روح لأعلى الشمال الشرقي واستخدم Lens of Truth عشان تتفادى الحفرة. اعبر الحفر المخفية لغرفة الـ Like Like؛ العنكبوت على الجدار ورا."),
"gs80": ("مفتاح الجنوب الشرقي وباب الغرفة الوسطى", "روح للزاوية الجنوبية الشرقية واستخدم الـ Lens عشان تلقى الفتحة اللي فيها Small Key. ادخل الغرفة الوسطى وافتح الباب الشمالي الشرقي، واعبر الحفرة على الممشى المخفي."),
"gs81": ("الباب الشمالي الغربي، Deku Baba", "بعد ما ينزل الماي، خذ الممر الغربي وغُص تحت حفرة الماي. أحرق التوابيت في الغرفة الجاية عشان Small Key، وافتح الباب الشمالي الغربي في الغرفة الوسطى. فيه Deku Baba يحرس العنكبوت."),
"gs82": ("B3، غرفة المنصات المخفية", "في B3، بعد المقاصل اللي تطيح والـ Stalfos، روح يسار (شرق) واعبر الفراغ بالـ Hover Boots فوق منصات مخفية. اهزم كل شي في الغرفة الجاية اللي فيها المنجل المخفي عشان ينفتح الباب البعيد."),
"gs83": ("B3، جدار غرفة الأشواك", "في B3، بعد المقاصل والـ Stalfos، روح يمين (غرب) للخمس Rupees الفضية. في الغرفة الجاية اسحب بلوك حجر عشان تتعدى الأشواك، بعدين اسحبه للجهة الثانية واطلع. العنكبوت على الجدار العلوي وراك."),
"gs84": ("B3، حفرة ممر الريح", "حل لغزين الـ Rupees الفضية وأنت رايح شمال للممرات اللي فيها تماثيل ريح. عند فراغ الـ Hover Boots، شوف تحت في الحفرة تلقى العنكبوت، واضربه بعد ما تعبر."),
"gs85": ("B4، القفص جنب السفينة", "جنب السفينة الراسية في B4، اطلع القفص اللي فيه بلوك الاختصار. فوق شغّل Scarecrow's Song عند ريح القش، سوّ Hookshot على Pierre، وتلقى العنكبوت على الجدار القريب."),
"gs86": ("B4، الجماجم اللي تدور", "اركب السفينة غرب وامشِ في متاهة الغرفة المخفية لين آخر غرفة غربية فيها ثلاث جماجم كبيرة تدور. ارمِ قنبلة في كل وحدة؛ وحدة فيها العنكبوت."),
"gs87": ("ورا خيمة النجارين", "اعبر الجسر المكسور بـ Epona أو بالـ Longshot. بالليل، ورا خيمة النجارين الجديدة، العنكبوت على جدار الأطلال."),
"gs88": ("القوس الصخري، الجهة الجنوبية", "اعبر الجسر المكسور، وفي المنطقة الجنوبية مقابل المخيم كسّر الصخور الكبيرة بالمطرقة. بالليل شوف فوق داخل القوس الصخري الطبيعي."),
"gs89": ("جدار المدخل أبو الستارة الحمرا", "بعد ما تصير الـ Gerudo معك، دوّر المدخل العالي الشمالي الشرقي اللي عليه قماش أحمر. بالليل العنكبوت على الجدار العالي يمين الباب."),
"gs90": ("هدف ميدان الرماية", "بالليل اركب Epona لميدان الرماية على الخيل، لين الزاوية الشمالية الشرقية. شوف ورا الهدف الكبير اللي فوق."),
"gs91": ("غرفة الأطلال", "اعبر الرمال المتحركة وامشِ مع العلامات لين الملجأ المهدوم في الصحراء. انزل السلّم بعيد عن الرمل لغرفة صغيرة فيها العنكبوت."),
"gs92": ("المنحدرات الشمالية، الـ Guays", "شغّل Sun's Song عشان يصير ليل، وشوف المنحدرات الشمالية اللي تتجمع فيها الـ Guays. العنكبوت على الجدار."),
"gs93": ("التربة اللينة عند المدخل", "بعد ما يعلمك Sheik أغنية الانتقال، ارجع وأنت صغير ومعك حشرة في قنينة وطلّعها على التربة اللينة جنب مدخل المعبد. ازرع Magic Bean هناك بعد، عشان عنكبوت ثاني بعدين."),
"gs94": ("الجدار الشبكي، النفق الشمالي الغربي", "وأنت صغير ازحف في النفق الشمالي الغربي وخذ الباب اللي يمين. في الغرفة اللي فيها الجدار الشبكي والـ Keese، العنكبوت على الجدار."),
"gs95": ("زاوية غرفة التمثال", "بعد ما تطلع للدور الثاني، خذ الطريق الشرقي لغرفة التمثال العملاق. شوف في الزاوية اليمين تحت جنب رجول التمثال المطوية."),
"gs96": ("غرفة الـ Beamos، يدين التمثال", "في الدور الثالث بغرفة التمثال، خذ الطريق الجنوبي الغربي لغرفة الشمس اللي فيها Beamos. انزل الممر الجنوبي باتجاه اليدين، لف وشوف فوق."),
"gs97": ("الهضبة جنب نبتة الفاصوليا", "وأنت صغير ازرع Magic Bean في التربة اللينة جنب مدخل المعبد. وأنت كبير بالليل، اركب النبتة الطايرة للهضبة المرتفعة الشمالية الشرقية اللي مستخبي فيها العنكبوت."),
"gs98": ("فتحة غرفة الصخور المنحنية", "وأنت كبير افتح الباب الشمالي الشرقي من صالة المدخل لغرفة الـ Half-pipe اللي تتدحرج فيها صخور. بعد البلوك الأزرق اللي يسار، شوف في الفتحة المكشوفة."),
"gs99": ("الدور الثالث، الزاوية العلوية في غرفة التمثال", "في الدور الثالث عند التمثال الكبير، امشِ مع الجهة الغربية لين الزاوية اليسار العلوية اللي فيها ريح. شغّل Scarecrow's Song وسوّ Hookshot للعنكبوت."),
"gs100": ("نفق الكهف المسدود بالصخور", "قرب نافورة الجنية العظيمة، شيل كومة الصخور السودا بالـ Silver Gauntlets عشان ينفتح كهف. استخدم Lens of Truth للـ Skulltulas المخفية، اطلع لين فوق، ولف تلقى العنكبوت."),
}
